  u jsonb; n int := 0;
begin
  for u in select * from jsonb_array_elements(p) loop
    update items
       set extra = jsonb_set(extra, '{photos}', u->'photos')
     where id = (u->>'id')::bigint and site_id = 106 and collection = 'products';
    if found then n := n + 1; end if;
  end loop;
  raise notice 'фото оновлено: %', n;
end
$ph$;

-- Що вийшло
select 'товарів із фото з нової теки' as що, count(*)::text as скільки
  from items where site_id = 106 and collection = 'products' and extra->'photos'->>0 like '%/img/n/%'
union all
select 'з них із 5 фото', count(*)::text
  from items where site_id = 106 and collection = 'products'
   and extra->'photos'->>0 like '%/img/n/%' and jsonb_array_length(extra->'photos') = 5;
